15	// framesSeen returns every FrameMsg a view was handed, oldest first.
16	func framesSeen(v *fakeView) []jobs.FrameMsg {
17		var out []jobs.FrameMsg
18		for _, msg := range v.received {
19			if typed, ok := msg.(jobs.FrameMsg); ok {
20				out = append(out, typed)
21			}
22		}
23		return out
24	}
25	
26	// stubAnimationEvery records the interval of every chain request and returns a
27	// Cmd that yields the tick at `at` immediately, without sleeping.
28	func stubAnimationEvery(t *testing.T, at time.Time) *[]time.Duration {
29		t.Helper()
30		var got []time.Duration
31		orig := animationEvery
32		animationEvery = func(d time.Duration, fn func(time.Time) tea.Msg) tea.Cmd {
33			got = append(got, d)
34			return func() tea.Msg { return fn(at) }
35		}
36		t.Cleanup(func() { animationEvery = orig })
37		return &got
38	}
39	
40	func TestOnlyOneAnimationChainIsEverAlive(t *testing.T) {
41		a := router(t, &fakeView{})
42		a.jobs.Start(scanRun("default", "a"))
43	
44		if a.ensureTick() == nil {
45			t.Fatal("no chain was started for work that is running")
46		}
47		if second := a.ensureTick(); second != nil {
48			t.Error("a second chain was started while the first was alive")
49		}
50		if !a.anim.ticking {
51			t.Error("the router does not know its chain is alive")
52		}
53	}
54	
55	func TestNoAnimationChainStartsWithNothingRunning(t *testing.T) {
56		a := router(t, &fakeView{})
57		if cmd := a.ensureTick(); cmd != nil {
58			t.Error("a chain was started with an empty registry")
59		}
60	}
61	
62	func TestTheChainStartsAtTheFastInterval(t *testing.T) {
63		got := stubAnimationEvery(t, time.UnixMilli(1000))
64		a := router(t, &fakeView{})
65		a.jobs.Start(scanRun("default", "a"))
66	
67		a.ensureTick()
68	
69		if len(*got) != 1 || (*got)[0] != animationFastInterval {
70			t.Errorf("chain intervals = %v, want one of %v", *got, animationFastInterval)
71		}
72	}
73	
74	func TestATickFromAnOlderChainIsDropped(t *testing.T) {
75		view := &fakeView{}
76		a := router(t, view)
77		a.jobs.Start(scanRun("default", "a"))
78		a.ensureTick()
79	
80		before := a.animationFrame()
81		_, cmd := a.Update(animationTickMsg{seq: a.anim.seq - 1, at: time.UnixMilli(1000)})
82	
83		if a.animationFrame() != before {
84			t.Error("a stale tick advanced the frame")
85		}
86		if cmd != nil {
87			t.Error("a stale tick was answered with a command")
88		}
89		if n := len(framesSeen(view)); n != 0 {
90			t.Errorf("a stale tick delivered %d FrameMsg, want 0", n)
91		}
92	}
93	
94	// A tick sends the frame and nothing else, and only to the view on screen.
95	func TestATickSendsAFrameAndNoSnapshot(t *testing.T) {
96		onScreen, offScreen := &fakeView{}, &fakeView{}
97		a := router(t, onScreen)
98		a.views[command.ViewWorkspaces] = offScreen
99		a.jobs.Start(scanRun("default", "a"))
100		a.jobsChanged()
101	
102		frames, snaps := len(framesSeen(onScreen)), len(jobsSeen(onScreen))
103		offFrames, offSnaps := len(framesSeen(offScreen)), len(jobsSeen(offScreen))
104	
105		a.Update(animationTickMsg{seq: a.anim.seq, at: time.UnixMilli(1000)})
106	
107		if got := len(framesSeen(onScreen)); got != frames+1 {
108			t.Errorf("the view on screen got %d FrameMsg, want %d", got-frames, 1)
109		}
110		if got := len(jobsSeen(onScreen)); got != snaps {
111			t.Errorf("the view on screen got %d new snapshots from a tick, want 0", got-snaps)
112		}
113		if got := len(framesSeen(offScreen)); got != offFrames {
114			t.Error("a view off screen got a FrameMsg")
115		}
116		if got := len(jobsSeen(offScreen)); got != offSnaps {
117			t.Error("a view off screen got a snapshot from a tick")
118		}
119	}
120	
121	func TestATickAdvancesTheFrameAndRenewsTheChain(t *testing.T) {
122		testutil.FastTimers(t, &animationFastInterval)
123		view := &fakeView{}
124		a := router(t, view)
125		a.jobs.Start(scanRun("default", "a"))
126		a.jobsChanged()
127	
128		before := a.animationFrame()
129		_, cmd := a.Update(animationTickMsg{seq: a.anim.seq, at: time.UnixMilli(1000)})
130	
131		if a.animationFrame() == before {
132			t.Error("the frame did not advance")
133		}
134		if _, ok := testutil.MsgOf[animationTickMsg](cmd); !ok {
135			t.Error("the chain was not renewed while work was running")
136		}
137	}
138	
139	func TestTheChainDiesWhenNothingRunsAndRestartsAfterwards(t *testing.T) {
140		testutil.FastTimers(t, &animationFastInterval)
141		view := &fakeView{}
142		a := router(t, view)
143		id := a.jobs.Start(scanRun("default", "a"))
144		a.jobsChanged()
145	
146		a.jobs.Advance(id, "a", jobs.ItemDone, "")
147		_, cmd := a.Update(animationTickMsg{seq: a.anim.seq, at: time.UnixMilli(1000)})
148	
149		if _, ok := testutil.MsgOf[animationTickMsg](cmd); ok {
150			t.Error("the chain renewed itself with nothing left to animate")
151		}
152		if a.anim.ticking {
153			t.Error("the router still believes a chain is alive")
154		}
155		a.jobs.Start(scanRun("default", "b"))
156		if a.ensureTick() == nil {
157			t.Error("a run started after the chain died got no chain")
158		}
159	}
160	
161	// Rule 122: the frame is bare, its rendering is not.
162	func TestTheFrameIsBareAndItsRenderingIsNot(t *testing.T) {
163		testutil.TrueColor(t)
164		view := &fakeView{}
165		a := router(t, view)
166		a.jobs.Start(scanRun("default", "a"))
167		a.jobsChanged()
168	
169		frames := framesSeen(view)
170		if len(frames) == 0 {
171			t.Fatal("the view on screen was never handed a FrameMsg")
172		}
173		f := frames[len(frames)-1]
174		if f.Frame == "" {
175			t.Fatal("no spinner frame was carried")
176		}
177		if strings.Contains(f.Frame, "\x1b") {
178			t.Errorf("Frame = %q carries an escape sequence; Rule 122", f.Frame)
179		}
180		if !strings.Contains(f.RenderedFrame, "\x1b") || !strings.Contains(f.RenderedFrame, f.Frame) {
181			t.Errorf("RenderedFrame = %q, want the styled Frame %q (Rule 128)", f.RenderedFrame, f.Frame)
182		}
183	}
184	
185	// The blink phase is read off the message's own time, not the wall clock.
186	func TestTheFrameCarriesThePhaseOfTheTickTime(t *testing.T) {
187		testutil.FastTimers(t, &animationFastInterval)
188		view := &fakeView{}
189		a := router(t, view)
190		a.jobs.Start(scanRun("default", "a"))
191		a.jobsChanged()
192	
193		for _, tt := range []struct {
194			ms   int64
195			want bool
196		}{{1000, true}, {1500, false}, {2000, true}} {
197			a.Update(animationTickMsg{seq: a.anim.seq, at: time.UnixMilli(tt.ms)})
198			frames := framesSeen(view)
199			if len(frames) == 0 {
200				t.Fatalf("tick at %d ms delivered no FrameMsg", tt.ms)
201			}
202			if got := frames[len(frames)-1].Blink; got != tt.want {
203				t.Errorf("tick at %d ms: Blink = %v, want %v", tt.ms, got, tt.want)
204			}
205		}
206	}
207	
208	// A view entering the screen gets the snapshot, then the frame.
209	func TestAViewEnteringTheScreenGetsTheSnapshotAndTheFrame(t *testing.T) {
210		ws := &fakeView{}
211		a := router(t, &fakeView{})
212		a.views[command.ViewWorkspaces] = ws
213		a.jobs.Start(scanRun("default", "a"))
214		a.anim.blinkOn = true
215	
216		a.switchView(command.ViewWorkspaces)
217	
218		changed, frame := -1, -1
219		for i, msg := range ws.received {
220			switch msg.(type) {
221			case jobs.ChangedMsg:
222				changed = i
223			case jobs.FrameMsg:
224				frame = i
225			}
226		}
227		if changed < 0 || frame < 0 {
228			t.Fatalf("entering view got ChangedMsg at %d and FrameMsg at %d, want both", changed, frame)
229		}
230		if changed > frame {
231			t.Error("the FrameMsg came before the ChangedMsg")
232		}
233		if got := framesSeen(ws)[0]; got.Blink != a.anim.blinkOn {
234			t.Errorf("entering FrameMsg.Blink = %v, want the router's %v", got.Blink, a.anim.blinkOn)
235		}
236	}
237	
238	// A registry change reaches every held view; the frame only the one on screen.
239	func TestARegistryChangeStillReachesEveryView(t *testing.T) {
240		onScreen, other := &fakeView{}, &fakeView{}
241		a := router(t, onScreen)
242		a.views[command.ViewWorkspaces] = other
243	
244		a.Update(jobs.StartMsg{Run: scanRun("default", "a")})
245	
246		for name, v := range map[string]*fakeView{"on screen": onScreen, "other": other} {
247			if len(jobsSeen(v)) == 0 {
248				t.Errorf("%s was not handed a ChangedMsg", name)
249			}
250		}
251		if len(framesSeen(onScreen)) == 0 {
252			t.Error("the view on screen was not handed a FrameMsg")
253		}
254		if len(framesSeen(other)) != 0 {
255			t.Error("a view off screen was handed a FrameMsg")
256		}
257	}
